<template><main ref="heading" class="page" tabindex="-1"><header><div><p class="eyebrow">ROOT · PUBLICATION</p><h1>{{t('publicPricingAdmin.title')}}</h1><p>{{t('publicPricingAdmin.description')}}</p></div><el-button :disabled="loading" @click="load">{{t('publicModelsAdmin.refresh')}}</el-button></header><el-alert v-if="error" role="alert" type="error" :closable="false" :title="errorTitle"><p v-if="error.requestId">{{t('publicModelsAdmin.requestId')}}: <code>{{error.requestId}}</code></p></el-alert><p class="status" aria-live="polite">{{statusText}}</p><PricingDiff :draft="draft" :live="live"/><PublicationChecks :result="checks" :loading="checking" @validate="validate"/><section class="panel publish" aria-labelledby="publish-title"><h2 id="publish-title">{{t('publicPricingAdmin.publishTitle')}}</h2><p>{{t('publicPricingAdmin.publishHelp')}}</p><el-alert v-if="workflow.pendingRecovery" type="warning" :closable="false" :title="t('publicPricingAdmin.pendingRecovery')"/><el-alert v-if="workflow.conflict" type="warning" :closable="false" :title="t('publicPricingAdmin.conflict')"/><el-alert v-if="workflow.error" role="alert" type="error" :closable="false" :title="workflowErrorTitle"><p v-if="workflow.error.requestId">{{t('publicModelsAdmin.requestId')}}: <code>{{workflow.error.requestId}}</code></p></el-alert><el-form label-position="top"><el-form-item :label="t('publicModelsAdmin.currentPassword')"><el-input ref="passwordInput" v-model="currentPassword" type="password" autocomplete="current-password" @keyup.enter="publish"/></el-form-item></el-form><el-button type="primary" :loading="workflow.busy" :disabled="workflow.busy||workflow.pendingOperation==='restore'||!validator.isCurrent(expectedRevision)||!currentPassword" @click="publish">{{workflow.pendingRecovery?t('publicPricingAdmin.retryPublish'):t('publicPricingAdmin.publish')}}</el-button></section><PriceSnapshotHistory :items="history" :busy="workflow.busy||workflow.pendingRecovery" :current-guid="live?.release?.guid" @restore="openRestore"/><el-dialog v-model="restoreOpen" :title="t('publicPricingAdmin.restoreTitle')" :close-on-click-modal="false" :close-on-press-escape="true" :show-close="true" :before-close="beforeRestoreClose" @closed="restoreClosed"><p>{{t('publicPricingAdmin.restoreHelp',{version:restoreTarget?.version??''})}}</p><el-form label-position="top"><el-form-item :label="t('publicModelsAdmin.currentPassword')"><el-input ref="restorePasswordInput" v-model="restorePassword" type="password" autocomplete="current-password" @keyup.enter="restore"/></el-form-item></el-form><template #footer><el-button v-if="workflow.pendingOperation==='restore'" @click="reconcileRestore">{{t('publicPricingAdmin.reconcile')}}</el-button><el-button @click="closeRestore">{{t('publicModelsAdmin.cancel')}}</el-button><el-button type="warning" :loading="workflow.busy" :disabled="workflow.busy||workflow.pendingOperation==='publish'||!restorePassword" @click="restore">{{t('publicPricingAdmin.restore')}}</el-button></template></el-dialog></main></template>
<script setup>import{computed,nextTick,onBeforeUnmount,onMounted,reactive,ref}from'vue';import{useI18n}from'@/composables/useI18n';import{publicPricingAdminApi,createPricingPublicationCoordinator,createPricingValidationCoordinator}from'@/api/publicPricingAdmin';import PricingDiff from'@/components/public-admin/PricingDiff.vue';import PublicationChecks from'@/components/public-admin/PublicationChecks.vue';import PriceSnapshotHistory from'@/components/public-admin/PriceSnapshotHistory.vue';const{t}=useI18n(),heading=ref(null),passwordInput=ref(null),restorePasswordInput=ref(null),draft=ref(null),live=ref(null),history=ref([]),loading=ref(false),error=ref(null),currentPassword=ref(''),restorePassword=ref(''),restoreOpen=ref(false),restoreTarget=ref(null),restoreTrigger=ref(null);const workflow=reactive({draft:null,history:[],busy:false,error:null,conflict:false,pendingRecovery:false}),coordinator=createPricingPublicationCoordinator({api:publicPricingAdminApi,state:workflow}),validation=reactive({draftRevision:null,result:null,loading:false,error:null}),validator=createPricingValidationCoordinator({api:publicPricingAdminApi,state:validation});const checks=computed(()=>validation.result),checking=computed(()=>validation.loading);let reads=new AbortController(),readGeneration=0;const expectedRevision=computed(()=>draft.value?.revision??null);const safe=e=>({code:e?.code??'request_failed',requestId:e?.requestId??null});const known=new Set(['authentication_required','root_required','revision_conflict','validation_failed','unavailable','network_error','action_verification_rejected','action_verification_conflict','action_inactive','action_rate_limited','action_dependency_unavailable']);const message=e=>t(`publicPricingAdmin.errors.${known.has(e?.code)?e.code:'request_failed'}`),errorTitle=computed(()=>message(error.value)),workflowErrorTitle=computed(()=>message(workflow.error)),statusText=computed(()=>loading.value?t('publicPricingAdmin.loading'):draft.value?t('publicPricingAdmin.loaded',{revision:draft.value.revision}):'');async function load(){reads.abort();reads=new AbortController();const generation=++readGeneration,signal=reads.signal;loading.value=true;error.value=null;validator.setRevision(null);try{const[d,h]=await Promise.all([publicPricingAdminApi.getDraft({signal}),publicPricingAdminApi.listReleases({signal})]);if(generation!==readGeneration)return;const newest=[...h.items].sort((a,b)=>b.version-a.version)[0]??null,nextLive=newest?await publicPricingAdminApi.getRelease(newest.guid,{signal}):null;if(generation!==readGeneration)return;draft.value=d;workflow.draft=d;validator.setRevision(d.revision);history.value=h.items;workflow.history=h.items;live.value=nextLive}catch(e){if(generation===readGeneration&&e?.name!=='AbortError')error.value=safe(e)}finally{if(generation===readGeneration)loading.value=false}}async function validate(){if(!draft.value||validation.loading)return;const result=await validator.validate();if(!result&&validation.error)error.value=validation.error}async function publish(){if(workflow.busy||!currentPassword.value||!validator.isCurrent(expectedRevision.value))return;const input={currentPassword:currentPassword.value};currentPassword.value='';const out=await coordinator.publish(input);if(out)await load();else if(workflow.conflict){validator.setRevision(null);await load()};nextTick(()=>passwordInput.value?.focus?.())}function openRestore(item,event){if(workflow.pendingRecovery)return;restoreTrigger.value=event?.currentTarget??document.activeElement;restoreTarget.value=item;restorePassword.value='';restoreOpen.value=true;nextTick(()=>restorePasswordInput.value?.focus?.())}function closeRestore(){restorePassword.value='';restoreTarget.value=null;restoreOpen.value=false}function beforeRestoreClose(done){if(workflow.pendingRecovery){coordinator.clearAttempt();void load()}restorePassword.value='';restoreTarget.value=null;done()}function restoreClosed(){restorePassword.value='';nextTick(()=>restoreTrigger.value?.isConnected?restoreTrigger.value.focus():heading.value?.focus?.());restoreTrigger.value=null}function reconcileRestore(){coordinator.clearAttempt();closeRestore();void load()}async function restore(){if(workflow.busy||!restoreTarget.value||!restorePassword.value)return;const target=restoreTarget.value,input={currentPassword:restorePassword.value};restorePassword.value='';const out=await coordinator.restore(target.guid,input);if(out){closeRestore();await load()}else if(workflow.conflict){validator.setRevision(null);closeRestore();await load()}}onMounted(()=>{heading.value?.focus?.();void load()});onBeforeUnmount(()=>{currentPassword.value='';restorePassword.value='';reads.abort();validator.cancel();coordinator.cancel()})</script>
<style scoped>.page{height:100%;overflow:auto;max-width:1400px;margin:auto;padding:24px;display:grid;gap:20px}.page>header{display:flex;justify-content:space-between;gap:16px}.eyebrow{letter-spacing:.12em;color:var(--text-secondary)}.panel{background:var(--el-bg-color);border:1px solid var(--el-border-color);border-radius:16px;padding:20px}.publish{max-width:700px}.status{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}code{font-family:ui-monospace,monospace}@media(max-width:768px){.page{padding:16px}.page>header{flex-direction:column}.page :deep(.el-dialog){width:calc(100vw - 32px)!important}}</style>
